def _post_deactivate_did(self, tenant: str, did: str) -> None:
    # POST /v1/dids/{did}/deactivate：
    # 请求体仅允许空体、{} 或恰含可选 reason；reason 提供时由
    # store 在确认非重复停用后校验（字符串裁剪后非空，否则 400），
    # 重复停用时任何 reason（含非法值）均忽略并返回首次结果。
